// Original QuickReply payload lives on the webhook node. Guard so testing a
// single node in isolation doesn't hard-crash.
let body = {};
try {
  body = $('QuickReply Webhook').first().json.body || {};
} catch (e) {
  const inp = $input.first();
  body = (inp && inp.json && (inp.json.body || inp.json)) || {};
}

const phone = body.phone || '';
const name = body.name || 'Customer';
const msgId = body.id || '';
const msgTime = Number(body.msg_time) || Date.now();
const payload = body.payload || {};
const text = payload.text || '';

// ---- Classify the message (confirmed from prod cloud-run logs) ----
//  text        -> _type USER_TEXT, has payload.text
//  image       -> _type USER_FILE, contentType image/jpeg
//  audio/voice -> _type USER_FILE, contentType audio/ogg, audioText ""
//  button tap  -> _type USER_LIST_REPLY / USER_BUTTON_REPLY
const ptype = String(payload._type || '').toUpperCase();
const contentType = String(payload.contentType || '').toLowerCase();
const hasText = !!(text && String(text).trim());

// MEDIA = any uploaded file: image, audio voice-note, report, document.
const isMedia = ptype === 'USER_FILE'
  || (!hasText && ptype && ptype !== 'USER_TEXT')
  || (!hasText && (contentType.startsWith('image/') || contentType.startsWith('audio/')));
let mediaKind = 'text';
if (isMedia) {
  if (contentType.startsWith('image/')) mediaKind = 'image';
  else if (contentType.startsWith('audio/')) mediaKind = 'audio';
  else mediaKind = 'file';
}
const mediaPath = payload.path || '';

// AUTOMATION / TEMPLATE triggers the AI must NOT answer - QuickReply's own flows
// already handle these (e.g. the Health Score CTA sends its link automatically).
// Add new predefined-button texts to AUTOMATION_TRIGGERS (matched case-insensitive).
// Matched as PATTERNS, not exact substrings. The literal-substring list missed the real
// button text "I want to Check My Free PCOD Health Score" - the word PCOD sits between
// "Free" and "Health Score", so none of the four literals matched, the AI was not skipped,
// and it answered by INVENTING a health score and a PCOD diagnosis. Patterns survive the
// wording changes a marketing team makes to a button; exact strings do not.
// Punctuation is stripped before matching, so "Health-Score" and "health score!" both work.
// Health-score phrasings are deliberately NOT here. The four literal button texts below are
// the ones QuickReply's own flow demonstrably answers. A NEW variant it does not recognise
// ("I want to Check My Free PCOD Health Score") produced only the generic
// "Hi! Please let us know how we can help you." - so skipping the AI on those would leave the
// customer with a greeting and no link at all. Anything else mentioning a health score now
// reaches the AI, where a deterministic responder sends the real link.
// >> If QuickReply is later configured to answer the PCOD variant too, add it here, or the
//    customer will get the link twice.
// The vaji-bati/kern-drops message ("Mujhe vaji bati or kern drop chahiye") is a
// HUMAN-HANDOFF case, handled by HUMAN_HANDOFF_RES below - NOT by this AUTOMATION list.
// History: it was a skip trigger, REMOVED 2026-07-31 when skipping produced silence (neither
// QuickReply nor, at the time, anything else answered it), then RE-ADDED 2026-08-11 with a
// different purpose: the AI must stay SILENT so a real agent takes over, and a separate
// calling automation fires on the same phrasing. Silence is intentional now - do not delete
// HUMAN_HANDOFF_RES expecting the AI to reply.
// >> ADDED 2026-08-04: "I want my detailed HealthScore360 report". QuickReply's flow answers
//    this one end to end - it posts "We're processing your HealthScore360 Report", then the
//    PDF itself. The AI was not skipped (the old pattern ended at "healthscore", so the
//    trailing "360 report" made it miss), so the report guard fired too and sent a SECOND
//    copy as a raw signed storage URL. The customer got the report twice.
//    Whitespace and the "360"/"report" tails are optional so the same entry survives
//    "healthscore360", "health score 360" and "HealthScore 360 Report".
const AUTOMATION_TRIGGER_RES = [
  /^\s*check my free health\s*score\s*(360)?\s*$/,
  /^\s*check free health\s*score\s*(360)?\s*$/,
  /^\s*i want my detailed health\s*score\s*(360)?\s*(report)?\s*$/
];
const textLc = String(text || '').toLowerCase().replace(/[^a-z0-9\s]/g, ' ').replace(/\s+/g, ' ').trim();
const isTriggerText = AUTOMATION_TRIGGER_RES.some(re => re.test(textLc));
// HUMAN-HANDOFF triggers: AI must NOT answer, but for the OPPOSITE reason to the automation
// triggers above - nothing automated *replies*. A real agent takes over and a separate
// calling automation fires on the same phrasing. Added 2026-08-11 for the vaji-bati/kern-drops
// buying message. Anchored to the full message (only this phrasing), tolerating drop/drops,
// or/aur, an optional leading "mujhe", and common spellings of chahiye. Add entries here only
// for phrasings you want handed to a human instead of answered by the AI.
const HUMAN_HANDOFF_RES = [
  /^\s*(mujhe\s+)?vaji\s*bati\s+(or|aur)\s+kern\s*drops?\s+(chahiye|chahie|chaiye|chahiya)\s*$/
];
const isHumanHandoffText = HUMAN_HANDOFF_RES.some(re => re.test(textLc));
const isButtonReply = ptype === 'USER_LIST_REPLY' || ptype === 'USER_BUTTON_REPLY';
const isAutomation = isTriggerText || isButtonReply || isHumanHandoffText;

// The AI answers ONLY real typed questions. Skip media + automation/button messages.
const skipAi = isMedia || isAutomation;
let skipReason = '';
if (isMedia) skipReason = 'media_' + mediaKind;
else if (isButtonReply) skipReason = 'button_reply';
else if (isHumanHandoffText) skipReason = 'human_handoff_trigger';
else if (isTriggerText) skipReason = 'automation_trigger';

return [{
  json: {
    phone,
    name,
    msgId,
    msgTime,
    text,
    msgType: ptype,
    isMedia,
    mediaKind,
    mediaPath,
    isAutomation,
    skipAi,
    skipReason,
    convId: phone.replace(/[^0-9]/g, ''),   // matches CF qrConvId()
    savedAt: new Date().toISOString()
  }
}];

const RESUME_AFTER_SILENCE_MS = 30 * 60 * 1000; // human-silence before AI resumes
// How far back an unanswered message can still count as part of THIS turn. Without it, a
// message QuickReply's own template "answered" months ago stays unanswered forever and gets
// replied to the next time the customer says anything: on 16 Sep a "Hi" was answered with the
// products from a 29 Jul ad click, and on 17 Sep "doctor kon h ?" was answered with the report
// link asked for on 11 Sep. Older messages still go to the model as history, never as the question.
const TURN_MAX_AGE_MS = 6 * 60 * 60 * 1000;

// This message's own trigger time (from the webhook). No static data - the whole
// decision is derived from the durable Firestore messages, so it works the same in
// test and production executions.
const src = $('Extract Message Details').first().json;
const phone = src.phone;
const name = src.name || 'Customer';
const myMsgTime = Number(src.msgTime) || 0;

// Surface WHY this execution did or did not reply, in the n8n executions list itself.
// 'Decide Process bowed out' is the single most common question about this workflow and
// answering it used to mean opening each execution one by one. No-op without customData.
const _tag = (o) => {
  try {
    $execution.customData.set('decision', String(o.reason || ''));
    if (o.recentUserText) $execution.customData.set('text', String(o.recentUserText).slice(0, 60));
  } catch (e) { /* paid feature; Tag Execution already logs when it is unavailable */ }
  return [{ json: o }];
};

// ---- per-number lists (global 'off' already short-circuited by "AI Enabled?") ----
let mode = 'on';
let testNumbers = ['+917300978845', '+918756112227'];
let blockedNumbers = [];
const toList = (v) => {
  if (!v) return [];
  const raw = Array.isArray(v) ? v.join(',') : String(v);
  return raw.split(',').map(s => s.trim()).filter(Boolean);
};
try {
  const cfg = $('Get AI Config').first().json;
  if (cfg && typeof cfg.mode === 'string' && cfg.mode.trim()) mode = cfg.mode.trim().toLowerCase();
  const tn = toList(cfg && cfg.testNumbers);
  if (tn.length) testNumbers = tn;
  blockedNumbers = toList(cfg && cfg.blockedNumbers);
} catch (e) {}

if (blockedNumbers.includes(phone)) return _tag({ phone, name, shouldProcess: false, reason: 'ai_blocked_number' });
if (mode === 'off') return _tag({ phone, name, shouldProcess: false, reason: 'ai_paused_global' });
if (mode === 'test' && !testNumbers.includes(phone)) return _tag({ phone, name, shouldProcess: false, reason: 'ai_test_mode_only' });

// ---- OTHER AUTOMATIONS own certain templated messages. If THIS turn is one of their
//      template texts, that automation handles it and Ananya must NOT answer - otherwise
//      two bots reply to the same message and confuse the customer (fragmented "Han",
//      "Boliye" replies etc). Add more exact texts to this list as needed. Matching is
//      case- and whitespace-insensitive; switch to `.some(x => n.includes(x))` for partial.
const OTHER_AUTOMATION_TEXTS = [
  'hurray! my next product is on you? tell me more!',
];
const _norm = s => String(s || '').replace(/\s+/g, ' ').trim().toLowerCase();
const _isOtherAutomation = t => { const n = _norm(t); return !!n && OTHER_AUTOMATION_TEXTS.includes(n); };
if (_isOtherAutomation(src.text)) {
  return _tag({ phone, name, shouldProcess: false, reason: 'other_automation_template', recentUserText: String(src.text || '').slice(0, 60) });
}

// ---- read messages from conversations/{convId}/messages ----
//   customer      = direction 'in'
//   AI reply      = out + senderKind 'AI'     (Save AI Message; legacy: messageBy 'AI')
//   human reply   = out + senderKind 'HUMAN'  (CRM composer / qrSendMessage) - HAS text
//                   OR an AGENT_PLACEHOLDER   (QuickReply dashboard)         - no text
let items = [];
try { items = $('Fetch Conversation History').all(); } catch (e) { items = []; }
const tval = m => Number(m.msgTime) || new Date(m.createdAt || 0).getTime();

// The AI sends via ONE fixed QuickReply agent account; a dashboard takeover comes from
// a DIFFERENT account, told apart by agentId.
const AI_AGENT_IDS = new Set(['u9ocdFtszn6BAXa7L_ag']);  // <- AI's own QuickReply send account(s)

// senderKind is stamped at write time and is never touched by the status callbacks, so
// it survives; messageBy and agentId are both overwritten in place by QuickReply's
// SENT/DELIVERED/READ callbacks and cannot be trusted on their own.
const isAiOut = m => m.senderKind === 'AI' || m.messageBy === 'AI';
const isHumanOut = m => !isAiOut(m) && (
     m.senderKind === 'HUMAN'
  || (m._type === 'AGENT_PLACEHOLDER' && !m.automationBy && !AI_AGENT_IDS.has(String(m.agentId || '')))
);

// Pass 1 - learn extra AI send accounts, but ONLY from messages explicitly marked as the
// AI's own. The old code learned from "any outbound message that has text", so a human
// agent's CRM reply (AGENT_TEXT + text) both counted as an AI reply AND registered that
// agent as an AI account - after which the bot never paused for them again.
for (const it of items) {
  const m = it && it.json; if (!m) continue;
  if (m.direction === 'out' && m.agentId && isAiOut(m)) AI_AGENT_IDS.add(String(m.agentId));
}

let latestInboundAt = 0, lastAiAt = 0, lastHumanAt = 0;
const inbound = [];
for (const it of items) {
  const m = it && it.json; if (!m) continue;
  const t = tval(m);
  if (m.direction === 'in') {
    latestInboundAt = Math.max(latestInboundAt, t);
    if (m.text && !_isOtherAutomation(m.text)) inbound.push({ t, text: String(m.text) });
    continue;
  }
  if (m.direction !== 'out') continue;
  if (isHumanOut(m)) { lastHumanAt = Math.max(lastHumanAt, t); continue; }
  if (isAiOut(m)) { lastAiAt = Math.max(lastAiAt, t); continue; }
  // Legacy / ambiguous outbound text, written before senderKind existed. Count it as the
  // AI: calling it "human" would read every historical AI reply as a takeover and
  // silence the bot on every chat it has ever answered.
  if (m.text && !m.placeholder && m._type !== 'BOT_PLACEHOLDER') lastAiAt = Math.max(lastAiAt, t);
}


// Everything the decision turned on, in one place and human-readable. IST because that is
// the only timezone anyone reading an n8n execution here cares about.
const _ist = (ms) => ms ? new Date(ms + 19800000).toISOString().replace('T', ' ').slice(0, 19) + ' IST' : '-';
const _dbg = () => ({
  latestInboundAt, myMsgTime, lastAiAt, lastHumanAt,
  latestInbound: _ist(latestInboundAt),
  thisMessage: _ist(myMsgTime),
  lastAi: _ist(lastAiAt),
  lastHuman: _ist(lastHumanAt),
  ageOfThisMessageMins: myMsgTime ? Math.round((Date.now() - myMsgTime) / 60000) : null,
  fetched: items.length,
});
console.log('[Decide Process] age=' + (myMsgTime ? Math.round((Date.now() - myMsgTime) / 60000) + 'min' : '?')
  + ' fetched=' + items.length
  + ' lastInbound=' + (latestInboundAt ? new Date(latestInboundAt).toISOString() : '-')
  + ' lastAi=' + (lastAiAt ? new Date(lastAiAt).toISOString() : '-')
  + ' lastHuman=' + (lastHumanAt ? new Date(lastHumanAt).toISOString() : '-'));

// ---- DEBOUNCE (Firestore-based): if a newer customer message arrived during the
//      wait, let THAT execution answer the whole batch - this one bows out. ----
if (latestInboundAt > myMsgTime) {
  return _tag({ phone, name, shouldProcess: false, reason: 'newer_message_wins', ..._dbg() });
}

// ---- HANDOFF: a human agent is actively handling this chat ----
// Once a human agent has sent ANYTHING in the last RESUME window, the AI backs off -
// even if an in-flight AI reply happened to land after the human's message. The AI
// resumes only after the human has been quiet for the whole window.
const now = Date.now();
const humanActive = lastHumanAt > 0 && (now - lastHumanAt) < RESUME_AFTER_SILENCE_MS;
if (humanActive) {
  return _tag({ phone, name, shouldProcess: false, reason: 'human_active', minsSinceHuman: Math.round((now - lastHumanAt) / 60000), ..._dbg() });
}

// ---- already answered? ANY reply (AI text or a genuine human reply) newer than the
//      latest customer message => this / a duplicate execution bows out. ----
// NOT a QuickReply automation/bot template - those don't answer the query.
const answeredAt = Math.max(lastAiAt, lastHumanAt);
if (latestInboundAt > 0 && latestInboundAt <= answeredAt) {
  return _tag({ phone, name, shouldProcess: false, reason: 'already_answered', ..._dbg() });
}

// ---- text of the current turn, for the product lookup ----
// "Fetch Product Matches" runs before "Build AI Prompt", so it cannot use that node's
// newMsgText. It must not use only the triggering message either: a customer who types
// "vaji bati" and then "price?" would have the product name in the PREVIOUS message and
// match nothing. This is the same unanswered-messages set Build AI Prompt assembles.
const turnFloor = Math.max(answeredAt, (myMsgTime || Date.now()) - TURN_MAX_AGE_MS);
let recentUserText = inbound.filter(m => m.t > turnFloor).map(m => m.text).join(' ');
if (!recentUserText && inbound.length) recentUserText = inbound[inbound.length - 1].text;
if (!recentUserText) recentUserText = String(src.text || '');
recentUserText = recentUserText.replace(/\s+/g, ' ').trim().slice(0, 300);

return _tag({ phone, name, shouldProcess: true, reason: 'process', recentUserText, resumedFromHuman: (lastHumanAt > 0 && lastHumanAt >= lastAiAt), ..._dbg() });

const decide = $('Decide Process').first().json;
const phone = decide.phone;
const name = decide.name || 'Customer';

let items = [];
try { items = $('Fetch Conversation History').all(); } catch (e) { items = []; }
const tval = m => Number(m.msgTime) || new Date(m.createdAt || 0).getTime();
const evs = items.map(i => i.json).filter(m => m && (m.msgTime || m.createdAt))
  .map(m => ({ ...m, _t: tval(m) })).sort((a, b) => a._t - b._t);

// Same classification as "Decide Process" - keep the two in sync. senderKind is stamped
// at write time and survives; messageBy and agentId are overwritten in place by
// QuickReply's status callbacks, so neither can be trusted on its own. A CRM-composer
// reply from a human agent is an AGENT_TEXT WITH text, which is exactly what an AI reply
// looks like - only senderKind tells them apart.
const AI_AGENT_IDS = new Set(['u9ocdFtszn6BAXa7L_ag']);
const isAiOut = m => m.senderKind === 'AI' || m.messageBy === 'AI';
const isHumanOut = m => !isAiOut(m) && (
     m.senderKind === 'HUMAN'
  || (m._type === 'AGENT_PLACEHOLDER' && !m.automationBy && !AI_AGENT_IDS.has(String(m.agentId || '')))
);
for (const m of evs) { if (m.direction === 'out' && m.agentId && isAiOut(m)) AI_AGENT_IDS.add(String(m.agentId)); }

const isHumanMsg = m => m.direction === 'out' && isHumanOut(m);
// legacy/ambiguous outbound text counts as the AI (see Decide Process for why)
const isAiMsg = m => m.direction === 'out' && !isHumanOut(m)
  && (isAiOut(m) || (!!m.text && !m.placeholder && m._type !== 'BOT_PLACEHOLDER'));

let lastAiAt = 0, lastHumanAt = 0, humanTextSeen = false;
for (const m of evs) {
  if (isHumanMsg(m)) { lastHumanAt = Math.max(lastHumanAt, m._t); if (m.text) humanTextSeen = true; }
  else if (isAiMsg(m)) lastAiAt = Math.max(lastAiAt, m._t);
}
const cutoff = Math.max(lastAiAt, lastHumanAt);
const resumedFromHuman = lastHumanAt > 0 && lastHumanAt >= lastAiAt;

// Same age floor as "Decide Process" - keep the two in sync. An unanswered message older than
// this is history, not the question being asked now (a 29 Jul ad message was answered on 16 Sep,
// a 11 Sep report request was answered on 17 Sep).
const TURN_MAX_AGE_MS = 6 * 60 * 60 * 1000;
const _triggerAt = Number(decide.myMsgTime) || (evs.length ? evs[evs.length - 1]._t : Date.now());
const turnFloor = Math.max(cutoff, _triggerAt - TURN_MAX_AGE_MS);

// current turn = inbound user messages not yet answered, and recent enough to still be the turn
const unanswered = evs.filter(m => m.direction === 'in' && m._t > turnFloor);
let newMsgText = unanswered.map(m => m.text || '').filter(Boolean).join('\n');
// Fallbacks so Gemini never receives an empty user message:
if (!newMsgText) {
  const lastUser = [...evs].reverse().find(m => m.direction === 'in' && m.text);
  if (lastUser) newMsgText = lastUser.text || '';
}
if (!newMsgText) {
  try { newMsgText = ($('Extract Message Details').first().json.text || '').trim(); } catch (e) {}
}

// transcript for context. A human agent's CRM reply HAS text, so feed it in as an
// assistant turn - the model then continues from what the human actually said instead of
// guessing. A QuickReply-dashboard takeover is text-less; those turns are invisible here
// and are flagged via the HANDOFF NOTE below.
const history = [];
for (const m of evs) {
  if (m.direction === 'in') { if (m._t > turnFloor) continue; history.push({ role: 'user', content: m.text || '' }); }
  else if (isHumanMsg(m)) { if (m.text) history.push({ role: 'assistant', content: m.text }); }
  else if (isAiMsg(m)) history.push({ role: 'assistant', content: m.text || '' });
}
const recentHistory = history.slice(-20);

const isFirstContact = !history.some(h => h.role === 'assistant');

// ---- AD CONTEXT (click-to-WhatsApp) ----
// A customer who taps the WhatsApp button on a Meta ad arrives with that ad attached to their
// FIRST inbound message, on preview.adPreview - headline, body copy and the fb.me link.
// Nothing read it, so on the one kind of chat where the ad is the ONLY context that exists the
// model was blind to it. 7 Aug: someone tapped "Chat with Women's Health Experts" (menstrual
// wellness), wrote "Hello" / "Isme kya hota hai" / "Kya help kariyega aap bataiye", and got an
// invented sexual-performance pitch - the exact opposite of what they came for. "Isme kya hota
// hai" is not a vague question at all once you know what "isme" points at.
// The adPreview shape is not stable across QuickReply payloads (headline and text have been
// seen at different depths), so fields are pulled out by NAME wherever they sit rather than by
// a fixed path, and the whole thing is wrapped so a malformed preview can never break a reply.
let adContext = '';
let adDebug = 'none';
try {
  const _firstIn = evs.find(m => m.direction === 'in' && m.preview);
  let _p = _firstIn && _firstIn.preview;
  if (typeof _p === 'string') { try { _p = JSON.parse(_p); } catch (e) { _p = null; } }
  const _ad = _p && typeof _p === 'object' ? (_p.adPreview || _p.ad || _p) : null;
  if (_ad && typeof _ad === 'object') {
    const _found = {};
    const _walk = (o, depth) => {
      if (!o || typeof o !== 'object' || depth > 4) return;
      for (const k of Object.keys(o)) {
        const v = o[k];
        const kl = k.toLowerCase();
        if (typeof v === 'string' && v.trim()) {
          if (!_found[kl] && (kl === 'headline' || kl === 'title' || kl === 'text' || kl === 'body' || kl === 'caption')) {
            _found[kl] = v.trim();
          }
        } else _walk(v, depth + 1);
      }
    };
    _walk(_ad, 0);
    const _headline = _found.headline || _found.title || '';
    const _body = String(_found.text || _found.body || _found.caption || '').replace(/\s+/g, ' ').slice(0, 300);
    if (_headline || _body) {
      adDebug = (_headline || _body).slice(0, 40);
      adContext = '\n\nAD CONTEXT (hard rule): this customer did not come looking for us - they tapped the '
        + 'WhatsApp button on one of our ads, and THIS is the ad they tapped:'
        + (_headline ? '\nAd headline: ' + _headline : '')
        + (_body ? '\nAd text: ' + _body : '')
        + '\n1. That ad is the subject they came to talk about. Open on THAT topic.'
        + '\n2. Their first messages will often be vague - "hello", "isme kya hota hai", "kya help karoge", '
        + '"price kya hai". Vague does NOT mean topic-less: they mean the ad. Ask them about the concern '
        + 'the ad is about instead of guessing a new one.'
        + '\n3. NEVER steer them to an unrelated health area, and never bring up a product or condition the '
        + 'ad did not mention - especially not sexual wellness, weight or performance unless the ad or the '
        + 'customer raised it.'
        + '\n4. Do not read the ad back to them, do not quote it, and do not say "aapne ad dekha tha". '
        + 'Just talk about the subject it was about.';
    }
  }
} catch (e) { adContext = ''; adDebug = 'error'; }

// ---- TIME AWARENESS: use the customer's OWN message time (msg_time), not Date.now() ----
let curMsgTime = 0;
if (unanswered.length) curMsgTime = unanswered[unanswered.length - 1]._t;
if (!curMsgTime) { const lu = [...evs].reverse().find(m => m.direction === 'in'); if (lu) curMsgTime = lu._t; }
if (!curMsgTime) { try { curMsgTime = Number($('Extract Message Details').first().json.msgTime) || 0; } catch (e) {} }
if (!curMsgTime) curMsgTime = Date.now();

const istNow = new Date(curMsgTime + (5.5 * 60 * 60 * 1000));
const H = istNow.getUTCHours();
const Min = istNow.getUTCMinutes();
const clock = (((H + 11) % 12) + 1) + ':' + String(Min).padStart(2, '0') + ' ' + (H < 12 ? 'AM' : 'PM') + ' IST';
let partOfDay = 'night';
if (H >= 5 && H < 12) partOfDay = 'morning';
else if (H >= 12 && H < 17) partOfDay = 'afternoon';
else if (H >= 17 && H < 21) partOfDay = 'evening';
const totalMinutes = H * 60 + Min;
const isOfficeHours = totalMinutes >= (9 * 60 + 30) && totalMinutes < (18 * 60 + 30);

// gap since the customer's PREVIOUS inbound message (how long they were away)
const firstUnansweredAt = unanswered.length ? unanswered[0]._t : curMsgTime;
let prevInboundAt = 0;
for (const m of evs) { if (m.direction === 'in' && m._t < firstUnansweredAt) prevInboundAt = Math.max(prevInboundAt, m._t); }
const gapMs = prevInboundAt ? (firstUnansweredAt - prevInboundAt) : 0;
function fmtGap(ms) {
  if (!ms) return 'first message / no prior';
  const min = Math.round(ms / 60000);
  if (min < 1) return 'just now';
  if (min < 60) return min + ' min ago';
  const hr = Math.round(min / 60);
  if (hr < 24) return hr + ' hr ago';
  const d = Math.round(hr / 24);
  return d + ' day' + (d > 1 ? 's' : '') + ' ago';
}
const gapLabel = fmtGap(gapMs);

let basePrompt = 'You are Ananya, a Health Expert at SehatUP.';
try {
  const docData = $('Get a document').first().json;
  if (docData && docData.body && docData.body.content && Array.isArray(docData.body.content)) {
    const extracted = docData.body.content
      .map(b => b.paragraph && b.paragraph.elements
        ? b.paragraph.elements.map(e => (e.textRun && e.textRun.content) ? e.textRun.content : '').join('')
        : '')
      .join('').trim();
