  s => /\b(team|doctor|manager|senior)\b[^.!?]{0,24}\b(se)\b[^.!?]{0,20}\b(confirm|pooch|puch|baat)\b[^.!?]{0,16}\b(kar\s*li\b|kar\s*liya\b|kar\s*diya\b|kar\s*di\b|liya\b)/i.test(s)
    || /\b(confirm|approve|approval)\b[^.!?]{0,20}\b(kar\s*li\b|kar\s*liya\b|ho\s*gaya\b|mil\s*gaya\b)/i.test(s));
flagSentences('offered_discount',
  'You cannot offer, approve or hint at any discount, lower price or free item. Hold the price warmly; any running offer comes from the team.',
  s => /\b(discount|chhut|chhoot|chut\b|offer|kam\s*kar|kam\s*karwa|kam\s*me|sasta|rebate)\b/i.test(s)
    && /\b(de\s*d|dedun|de\s*dun|kar\s*d|karwa|dilwa|mil\s*ja|ho\s*ja|check\s*kar|confirm)\b/i.test(s));
flagSentences('claimed_viewed',
  'You cannot see photos or videos. Never say you saw or checked them; ask them kindly to describe it in words.',
  s => /\b(maine|mai\s*ne|main\s*ne)\b[^.!?]{0,24}\b(dekh|dekha|dekhi|dekhli)\w*\b/i.test(s)
    || /\b(dekh\s*liya|dekh\s*li|dekh\s*lia|check\s*kar\s*liya)\b/i.test(s));

{
  const _maleConcern = /\b(timing|time\s*kam|jaldi\s*nikal|nikal\s*jata|discharge|premature|erection|erect\w*|ling|penis|land\b|size\s*chota|chota\s*size|mota\s*karna|veerya|virya|shukranu|sperm|night\s*fall|nightfall|swapnadosh|dhat|napunsak|mardana|marad|stamina\s*sex|sex\s*karta|sambhog)\b/i.test(_custAll);
  const _femaleContext = /\b(period|periods|mahwari|mahavari|pcod|pcos|pregnan\w*|garbh\w*|conceiv\w*|breast\s*feed\w*|breastfeed\w*|menopaus\w*|ovary|ovaries|bacchedani|uterus|delivery\s*hui)\b/i.test(_custAll);
  if (_maleConcern && !_femaleContext) {
    flagSentences('pregnancy_question',
      'The customer described a male concern. Do not ask about pregnancy or breastfeeding. If a safety question is needed, ask one neutral line: koi health problem hai ya koi dawai chal rahi hai?',
      s => /\b(pregnan\w*|pregnency|garbh\w*|breast\s*feed\w*|breastfeed\w*|feeding\s*kara|doodh\s*pila|conceiv\w*)\b/i.test(s)
        && /\?|\bnahi\s*hai\b|\bto\s*nahi\b|\bkya\b/i.test(s));
  }
}

const _SAFETY_CLAIM_RE = new RegExp(
     '\\b(side\\s*effects?|nuksan|nuksaan|haani)\\b[^.!?]{0,24}\\b(nahi|nhi|nai)\\b'
  + '|\\bno\\s+side\\s*effects?\\b'
  + '|\\b100\\s*(%|percent|pratishat)\\s*(safe|sure|cure|guaranteed?|result)\\b'
  + '|\\b(bilkul|puri\\s*tarah|puri\\s*trah|totally|completely)\\s*safe\\b'
  + '|\\b(guarantee|guaranteed)\\b[^.!?]{0,20}\\b(result|cure|ilaj|theek|thik)\\b', 'i');
flagSentences('safety_claim',
  'Never claim a product has no side effects, is 100% safe, or guarantees a result. Say the doctor can advise based on their health history.',
  s => _SAFETY_CLAIM_RE.test(s));

const _custWords = newMsgText.trim().split(/\s+/).filter(Boolean).length;
const _custSaidSomething = _custWords >= 12 || newMsgText.trim().length >= 70;
const _weAskedQuestion = /\?/.test(_lastOutText)
  || /\b(bata\s*d(o|ijiye|ena)|bataiye|batao|bta\s*d(o|ijiye)|kitni|kitna|kitne|kab\s*se|kaunsa|konsa|kaun\s*sa|kya\s*problem|naam)\b/i.test(_lastOutText);
const _custAskedQuestion = /\?/.test(newMsgText)
  || /\b(kya|kyu|kyun|kyo|kyon|kaise|kese|kaisa|kaisi|kab|kahan|kaha|kaun|kaunsa|konsa|kis|kisliye|kitna|kitni|kitne|batao|bataiye|bta|btao|btaiye|samjhao|samjhaiye|explain|tell)\b/i.test(newMsgText);
const _alreadyFlaggedAnswer = violations.some(v => /^(empty|booking_time_ignored|booking_name_ignored|product_answer_missing|consult_mode_unanswered|dose_not_deferred|report_link_missing)/.test(v.code));
if (aiText.trim() && !_alreadyFlaggedAnswer && qrIsNonAnswer(aiText) && (_custSaidSomething || _weAskedQuestion || _custAskedQuestion)) {
  flag('filler_reply', 'quality', _custSaidSomething
    ? 'The customer described their problem in detail and your draft was only filler. Acknowledge what they shared in your own words, reassure them that they are not alone and that you are with them in this, and ask one caring follow-up question.'
    : (_custAskedQuestion
      ? 'They asked a question and your draft did not answer it. Answer it directly and warmly. If only a doctor can answer it, say so kindly.'
      : 'They answered your question. Acknowledge their answer and move the conversation forward with care.'));
}

{
  const _normReply = (s) => String(s || '').toLowerCase().replace(/[^a-z0-9 ]+/g, ' ').replace(/\s+/g, ' ').trim();
  const _now = _normReply(aiText), _prev = _normReply(_lastOutText);
  if (_now && _prev && (_now === _prev || (_now.length >= 12 && (_prev.includes(_now) || _now.includes(_prev))))) {
    flag('repeat', 'quality',
      'Your draft repeats your previous message. Say something new that responds to their latest message.');
  }
}

{
  const _custWantsConsult = /\b(consult\w*|doctor|dr|daktar|appointment|salah)\b/i.test(_custAll)
    || /\bcall\s*(karwa|karva|karwao|karvao|kar\s*do|kar\s*dijiye|chahiye|aayega|aaega|kab)\b/i.test(_custAll)
    || /\bbaat\s*(karni|karna|karwa|karva|kara|ho\s*sakti|ho\s*sakta)\b/i.test(_custAll)

    || /\b(call|phone)\s*(me|karo|kro|kar\s*lo|kijiye|kariye|kar\s*sakt\w*)\b/i.test(_custAll);
  const _safetyRaised = /\b(thyroid|sugar|diabetes|diabetic|bp|blood\s*pressure|heart|kidney|liver|pregnan\w*|breastfeed\w*|surgery|operation)\b/i.test(_custAll)
    || /\b(dawai|dawa|medicine|tablet|goli)\b[^.!?]{0,20}\b(chal\s*rahi|chal\s*raha|le\s*rah\w*|leta|leti|lete)\b/i.test(_custAll);
  const _offeredBefore = _outs.some(m => /\bconsult/i.test(String(m.text)));
  const _exempt = _custWantsConsult || _safetyRaised || askedDose || _rx.length > 0 || _consultModeQ;
  const _mentionsConsult = /\bconsult/i.test(aiText);
  const _asksNameOrTime = /(\bnaam\b[^.!?]{0,24}\b(bata|batao|bataiye|dijiye)|kaunsa\s*time|konsa\s*time|kis\s*time|time\s*bata)/i.test(aiText);
  if (!_exempt && _asksNameOrTime && !_offeredBefore) {
    flag('booking_ask_unrequested', 'quality',
      'The customer has not asked for a consultation, so do not ask for their name or a call time. Keep helping them with their concern.');
  } else if (!_exempt && _mentionsConsult && _productQ && _matches.length && !_consultTopic) {
    flag('consultation_on_direct_sale', 'quality',
      'This product is sold directly. Do not pitch a consultation - give the price and link, then ask in one line whether they have any health problem or take any regular medicine.');
  } else if (!_exempt && _mentionsConsult && !_productQ && !_offeredBefore && _aiTurns < 2) {
    flag('consultation_too_early', 'quality',
      'It is too early to bring up the consultation - the customer has not asked for it. First comfort them and understand their problem: acknowledge what they said, reassure them that they are not alone and that you are with them, and ask one caring question. Do not mention the consultation yet.');
  }
}

const _codes = violations.map(v => v.code);
const _baseMessages = Array.isArray(buildData.messages) ? buildData.messages : [];

if (violations.length && !lastChance && _baseMessages.length) {

  const messages = JSON.parse(JSON.stringify(_baseMessages));
  const _notes = violations.map(v => v.note).filter((n, i, a) => a.indexOf(n) === i);
  messages[0].content = String(messages[0].content || '')
    + '\n\nREWRITE NOTE (read this before replying): you drafted this reply to the customer\'s latest message:\n"""\n'
    + (_rawModelText || '(empty)') + '\n"""\nIt cannot be sent because:\n'
    + _notes.map((n, i) => (i + 1) + '. ' + n).join('\n')
    + '\nWrite a NEW reply to the customer\'s latest message that fixes all of this and still follows every rule above. Reply with the message text only - warm, natural, 1 to 3 short lines. Never mention this note.';
  console.log('[Check Reply] attempt ' + (attempt + 1) + '/' + MAX_ATTEMPTS + ' -> retry | ' + _codes.join(',')
    + ' | draft=' + JSON.stringify(_rawModelText.slice(0, 80)));
  try { $execution.customData.set('attempt' + (attempt + 1), _codes.join(',').slice(0, 200)); } catch (e) {}
  return [{ json: { route: 'retry', attempt: attempt + 1, violations: _codes, messages } }];
}

let finalText = aiText;
let route = 'send';
const _safety = violations.filter(v => v.severity === 'safety');
if (_safety.length) {
  const _preds = _safety.map(v => v.bad);
  finalText = qrKeepSentences(aiText, s => !_preds.some(p => p(s)));
  if (_preds.some(p => _sentences(finalText).some(s => p(s)))) finalText = '';
}
if (!finalText.trim() || (_safety.length && qrIsNonAnswer(finalText))) {
  route = 'human';
  finalText = '';
}

const aiGuards = _codes.concat(attempt ? ['attempts=' + (attempt + 1)] : []).concat(route === 'human' ? ['needs_human'] : []).join(',');
try {
  $execution.customData.set('reply', String(finalText).slice(0, 60));
  $execution.customData.set('guards', aiGuards || 'none');
} catch (e) {  }
console.log('[Check Reply] attempt ' + (attempt + 1) + '/' + MAX_ATTEMPTS + ' -> ' + route
  + ' | ' + (aiGuards || 'clean') + ' | reply=' + JSON.stringify(String(finalText).slice(0, 60)));

return [{
  json: {
    route,
    phone,
    name,
    lastAiReply: finalText,
    aiGuards,
    violations: _codes,
    attempts: attempt + 1,
    needsHuman: route === 'human',
    lastUserMessage: newMsgText,
    docId: String(phone).replace(/[^0-9]/g, ''),
    emptyReason,
    lastUpdated: new Date().toISOString()
  }
}];

// After the WhatsApp send: capture the id QuickReply returned (data.id) so the
// message doc is keyed by it - then the CF's forwarded SENT/DELIVERED/READ status
// callbacks update THIS doc in place instead of making a "Bot replied" placeholder.
const send = $input.first().json || {};
let sentId = null;
const cands = [send.id, send.messageId, send.message_id,
  send.data && send.data.id, send.data && send.data.messageId,
  send.message && send.message.id, send.result && send.result.id];
for (const c of cands) { if (c) { sentId = String(c); break; } }

const ai = $('Final Reply').first().json;
const now = Date.now();
const convId = String(ai.phone || '').replace(/[^0-9]/g, '');
const msgId = sentId || ('local_' + now + '_' + Math.floor(Math.random() * 1e6));

// WHY the bot said what it said, stored next to the message itself. n8n Cloud prunes
// executions, so an n8n-only record disappears exactly when you need it for a complaint that
// came in last week - and console.log lines are per-execution and not searchable across
// chats. This lands in Firestore, so it is queryable and shows in the CRM beside the reply.
// Built in Extract AI Response, where the guard flags live, so the list of guards exists in
// exactly one place.
const aiGuards = String(ai.aiGuards || '');

console.log('QR send response (first 200):', JSON.stringify(send).slice(0, 200), '| id:', sentId,
  '| guards:', aiGuards || 'none');

return [{
  json: {
    convId,
    msgId,
    id: msgId,
    phone: ai.phone,
    direction: 'out',
    aiGuards,
    // messageBy is overwritten by QuickReply's status callback ('AI' -> 'AGENT'), and so
    // is agentId - both end up identical to a human agent's CRM reply. senderKind is
    // written once here and never touched again, so it is the ONLY field that lets
    // "Decide Process" tell the AI's own replies apart from a human takeover.
    senderKind: 'AI',
    messageBy: 'AI',
    _type: 'AGENT_TEXT',
    text: ai.lastAiReply,
    status: 'SENT',
    msgTime: now,
    createdAt: new Date().toISOString()
  }
}];

const phone = $('Record AI Sent').first().json.phone || 'unknown';
const aiText = $('Record AI Sent').first().json.text || '';
console.log('WhatsApp reply sent to:', phone, '| Reply:', aiText.substring(0, 50));
return [{json: {success: true, phone, aiReplyPreview: aiText.substring(0, 100), timestamp: new Date().toISOString()}}];

const b = ($('QuickReply Webhook').first().json.body) || {};

// Match "Is Real User Message?" EXACTLY: a real message is one that has a payload.
// This used to test `b.payload._type`. QuickReply does not always send _type - the
// workflow's own pinned sample body has a payload with text and no _type - so such a
// message was tagged STATUS, its `text` tag was never set, and the execution looked
// like a delivery callback in the list. That is why real conversations could not be
// found among the hundreds of SENT/DELIVERED/READ executions.
const isStatus = !b.payload;

const tags = {
  kind: isStatus ? 'STATUS' : 'MESSAGE',
  phone: String(b.phone || ''),
};
if (isStatus) {
  tags.event = String(b.event || '');
  tags.by = String(b.messageBy || '');
} else {
  tags.text = String((b.payload && b.payload.text) || '').slice(0, 60);
  // Kept so a media/button message is identifiable in the list without opening it.
  tags.ptype = String((b.payload && b.payload._type) || 'none');
}

// customData is a PAID n8n feature and is stored on PRODUCTION executions only - a manual
// run never keeps it. The old code swallowed the failure with a bare comment, so "no tags
// in the executions list" was indistinguishable from "this plan does not support tags".
// Log it instead: one line in the execution log tells you which of the two it is.
// Limits: 10 keys per execution, key <= 50 chars, value <= 512 chars.
try {
  for (const k of Object.keys(tags)) $execution.customData.set(k, tags[k]);
} catch (e) {
  console.log('[Tag Execution] customData NOT saved - ' + e.message
    + ' (paid feature, and production executions only). Tags attempted: ' + JSON.stringify(tags));
}

return $input.all();

const s = $json || {};
console.log('[Skip AI] reason=' + (s.skipReason || '') + ' | phone=' + (s.phone || '') + ' | type=' + (s.msgType || '') + ' | text=' + String(s.text || '').slice(0, 40));
return [{ json: { skipped: true, reason: s.skipReason, phone: s.phone, msgType: s.msgType, mediaKind: s.mediaKind } }];

// Flight-recorder: build ONE record for this execution AND post it to qrLogRun (Firestore
// `ai_runs`) directly from this node — there is NO separate HTTP node whose body field can be
// misconfigured (that was the "every row is empty" bug). This turns "why didn't the bot reply
// to X?" into a Firestore QUERY instead of opening executions one by one in the n8n UI.
//
// Wire this ONE Code node onto EVERY terminal branch of the main workflow (nothing after it):
//   Log Skipped                       --> Build Run Log
//   Process or Skip?  (FALSE output)  --> Build Run Log
//   Log Success                       --> Build Run Log
//
// One body covers all three. The outcome is INFERRED from how far the message got, so there
// is nothing to edit per branch. Every upstream read is guarded because each branch can see
// a different subset of nodes — the skip branch runs BEFORE Decide Process, so that node has
// not executed there, and Extract AI Response only exists on the reply branch.
const pick = (name) => { try { return $(name).first().json || {}; } catch (e) { return {}; } };

const src  = pick('Extract Message Details');   // present on all three branches
const dec  = pick('Decide Process');            // absent on the skip branch
const ai   = pick('Final Reply');               // present once the reply check finished (sent or needs_human)
const prod = pick('Fetch Product Matches');     // present on the reply branch
const rc   = pick('Recheck Handoff');           // present only when a reply was about to be sent

// Infer outcome from how far this message travelled.
let outcome = 'replied';
if (src.skipAi === true) outcome = 'skipped';
else if (dec.shouldProcess === false) outcome = 'bowed_out';
else if (ai.route === 'human') outcome = 'needs_human';   // every draft broke a safety rule - nothing was sent
else if (rc.okToSend === false) outcome = 'bowed_out';    // a human agent replied while Gemini was drafting - nothing was sent

const reason = outcome === 'skipped'   ? (src.skipReason || '')
             : outcome === 'bowed_out' ? (rc.okToSend === false ? rc.reason : (dec.reason || ''))
             : (dec.reason || 'process');

// n8n execution id — makes the Firestore doc idempotent and lets the Error Trigger's failure
// record MERGE onto the same doc as the run it belongs to.
let executionId = '';
try { executionId = String($execution.id || ''); } catch (e) {}

// Only the guards that actually FIRED, so the doc stays small and you can query a single one:
//   ai_runs  where  guards.doseGuard != null
const guards = {};
for (const code of (Array.isArray(ai.violations) ? ai.violations : [])) guards[String(code).split(':')[0]] = true;

// Firestore rejects `undefined`, so every optional value falls back to null / '' / [].
const run = {
  executionId,
  phone:  src.phone || dec.phone || '',
  name:   src.name  || dec.name  || 'Customer',
  convId: src.convId || '',
  ts:     Number(src.msgTime) || Date.now(),
  outcome,
  reason,
  input: {
    text:      src.text || '',
    msgType:   src.msgType || '',
    isMedia:   !!src.isMedia,
    mediaKind: src.mediaKind || '',
  },
  decision: {
    shouldProcess:  dec.shouldProcess === undefined ? null : dec.shouldProcess,
    latestInbound:  dec.latestInbound || null,      // human-readable IST from Decide Process
    thisMessage:    dec.thisMessage || null,
    lastAi:         dec.lastAi || null,
    lastHuman:      dec.lastHuman || null,
    ageMins:        dec.ageOfThisMessageMins === undefined ? null : dec.ageOfThisMessageMins,
    fetched:        dec.fetched === undefined ? null : dec.fetched,
    minsSinceHuman: dec.minsSinceHuman === undefined ? null : dec.minsSinceHuman,
    recentUserText: dec.recentUserText || '',
  },
  products: Array.isArray(prod.matches)
    ? prod.matches.map(p => (p && (p.title || p.name)) ? (p.title || p.name) : String(p)).slice(0, 10)
    : [],
  ai: {
    replied:       outcome === 'replied',
    reply:         ai.lastAiReply || '',
    guardsSummary: ai.aiGuards || '',   // compact string, e.g. "price=ambiguous,dose"
    emptyReason:   ai.emptyReason || '',
    attempts:      Number(ai.attempts) || 0,
    needsHuman:    ai.route === 'human',
    guards,                             // map of only-the-fired guards
  },
};

// POST straight to qrLogRun from inside this node, so there is NO separate HTTP node whose
// body field can be misconfigured. Requires this node's Mode = "Run Once for All Items" (the
// default). Wrapped so a logging failure can never break the flow — the customer's reply
// already went out upstream. If you keep this, DELETE the old "Log Run" HTTP node, or it will
// keep writing empty rows next to these good ones.
try {
  await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://us-central1-sehatup-f96b5.cloudfunctions.net/qrLogRun',
    body: run,
    json: true,
  });
} catch (e) {
  console.log('[Build Run Log] qrLogRun POST failed: ' + e.message);
}

return [{ json: run }];

// The single, final result of the reply check. Extract AI Response can run up to 3 times
// (each retry loops back through Call Gemini AI), so everything downstream reads THIS node,
// which runs exactly once per execution.
return $input.all();

// ============================================================================================
// RECHECK HANDOFF - last-moment "did a human agent reply?" guard, right before sending.
//
// Why: Decide Process checks for a human agent BEFORE the context lookups + Gemini call, so
// Gemini tokens are not spent on chats a human already owns. But an agent can reply during
// that 10-60s gap, and the customer then gets the agent's message AND the AI's reply within
// a minute. This re-reads Firestore just before sending and drops the AI reply if a human
// has replied since Decide Process looked.
//
// WIRING (3 new nodes, inserted between "Final Reply" and "Send WhatsApp Reply"):
//
//   Final Reply --> Re-fetch History --> Recheck Handoff --> Still OK to Send? --true--> Send WhatsApp Reply
//                                                                             \-false-> Log Skipped (or nothing)
//
// 1) "Re-fetch History"  = duplicate "Fetch Conversation History", change ONLY Collection to:
//      {{ 'conversations/' + $('Extract Message Details').first().json.phone.replace(/[^0-9]/g, '') + '/messages' }}
//    Keep: Operation Get Many, Limit 500, Settings > Always Output Data ON,
//          Settings > On Error "Continue".
//
// 2) "Recheck Handoff"   = Code node, Mode "Run Once for All Items", paste EVERYTHING below.
//
// 3) "Still OK to Send?" = IF node, condition Boolean:  {{ $json.okToSend }}  is true
//
// Nothing else changes: Send WhatsApp Reply reads $('Final Reply') by name, and Record AI Sent
// still sits directly after Send, so its $input is still the send response.
// ============================================================================================

const src = $('Decide Process').first().json;

// Same human/AI rules as Decide Process - keep the two in sync.
const AI_AGENT_IDS = new Set(['u9ocdFtszn6BAXa7L_ag']);  // <- AI's own QuickReply send account(s)
const isAiOut = m => m.senderKind === 'AI' || m.messageBy === 'AI';
const isHumanOut = m => m.direction === 'out' && !isAiOut(m) && (
     m.senderKind === 'HUMAN'
  || (m._type === 'AGENT_PLACEHOLDER' && !m.automationBy && !AI_AGENT_IDS.has(String(m.agentId || '')))
);
const tval = m => Number(m.msgTime) || new Date(m.createdAt || 0).getTime();

let lastHumanAt = 0;
for (const it of $input.all()) {
  const m = it && it.json; if (!m) continue;
  if (isHumanOut(m)) lastHumanAt = Math.max(lastHumanAt, tval(m));
}

// Only a human reply NEWER than what Decide Process already saw counts: older ones were
// handled there (30-min resume window), so this never double-blocks.
const seenByDecide = Number(src.lastHumanAt) || 0;
const humanJumpedIn = lastHumanAt > seenByDecide;

if (humanJumpedIn) {
  try { $execution.customData.set('decision', 'human_replied_during_ai'); } catch (e) {}
  console.log('[Recheck Handoff] human replied at ' + new Date(lastHumanAt).toISOString() + ' - AI reply dropped');
}

return [{ json: {
  okToSend: !humanJumpedIn,
  reason: humanJumpedIn ? 'human_replied_during_ai' : 'ok',
  phone: src.phone,
  lastHumanAt,
  seenByDecide,
} }];
